import{_ as a,o as l,c as s,a2 as o}from"./chunks/framework.BS0bAV7E.js";const h=JSON.parse('{"title":"L1 指南：共享对象加载器","description":"","frontmatter":{},"headers":[],"relativePath":"zh/l1/solib-loader.md","filePath":"zh/l1/solib-loader.md"}'),n={name:"zh/l1/solib-loader.md"};function d(t,e,c,p,r,i){return l(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="l1-指南-共享对象加载器" tabindex="-1">L1 指南：共享对象加载器 <a class="header-anchor" href="#l1-指南-共享对象加载器" aria-label="Permalink to &quot;L1 指南：共享对象加载器&quot;">​</a></h1><p><code>libs/ld_so.c</code> - 一个真正的内核动态加载器，被 L1 模块和动态链接的用户程序共同使用。</p><h2 id="接口面-l1-l1-wp8b-h" tabindex="-1">接口面（l1/l1_wp8b.h） <a class="header-anchor" href="#接口面-l1-l1-wp8b-h" aria-label="Permalink to &quot;接口面（l1/l1_wp8b.h）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>elf_load_dynamic(elf_data, size, name)    -&gt; load + relocate</span></span>
<span class="line"><span>ldso_run()                                 -&gt; run loaded objects&#39; init</span></span>
<span class="line"><span>so_load(name, flags) / so_unload(handle)</span></span>
<span class="line"><span>symbol_resolve(handle, name)</span></span>
<span class="line"><span>dlopen_impl(name, flags) / dlsym_impl(handle, name) / dlclose_impl(handle)</span></span>
<span class="line"><span>reloc_apply(rela, count, base, ...)</span></span>
<span class="line"><span>elf_get_needed(elf_data, size, ...)</span></span></code></pre></div><h2 id="处理内容" tabindex="-1">处理内容 <a class="header-anchor" href="#处理内容" aria-label="Permalink to &quot;处理内容&quot;">​</a></h2><p>ELF 动态对象：DT_NEEDED 链表（<code>elf_get_needed</code>）、符号表、重定位处理（<code>reloc_apply</code> - R_X86_64_RELATIVE/GLOB_DAT/JUMP_SLOT/64 系列）、<code>ldso_run</code> 时的初始化数组，以及带引用处理的卸载功能。</p><h2 id="功能验证" tabindex="-1">功能验证 <a class="header-anchor" href="#功能验证" aria-label="Permalink to &quot;功能验证&quot;">​</a></h2><p><code>userprogs/</code> 目录下的程序在 ring 3 层面测试了每个角落：<code>run dyn_hello</code>、<code>run so_test</code>、<code>run dlsym_test</code>、<code>run pie_test</code>、<code>run reloc_test</code>，并且 <code>ext_wp8b_selftest()</code> 在内核中对加载器进行了自检。如果你的模块通过此路径加载，这些就是你的回归测试基准点。</p><h2 id="位置无关性" tabindex="-1">位置无关性 <a class="header-anchor" href="#位置无关性" aria-label="Permalink to &quot;位置无关性&quot;">​</a></h2><p>PIE 对象通过相同的 <code>reloc_apply</code> 进行重定位；加载器的基地址分配使得 <code>-fno-pie</code> 内核代码和 PIE 模块能够共存 - 具体的重定位组合请参见 <code>pie_test</code> 源码。</p>`,10)])])}const u=a(n,[["render",d]]);export{h as __pageData,u as default};
